BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='500ms';
SET LOCAL application_name='ce1_ce101_inventory';
SELECT jsonb_build_object(
 'captured_at',clock_timestamp(),
 'current_database',current_database(),'read_only',current_setting('transaction_read_only'),
 'statement_timeout',current_setting('statement_timeout'),'lock_timeout',current_setting('lock_timeout'),
 'activity',(SELECT jsonb_build_object('client_connections',count(*) FILTER(WHERE backend_type='client backend'),'active',count(*) FILTER(WHERE state='active'),'waiting_lock',count(*) FILTER(WHERE wait_event_type='Lock'),'idle_in_transaction',count(*) FILTER(WHERE state LIKE 'idle in transaction%')) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid()),
 'inventory_columns',(SELECT jsonb_agg(jsonb_build_object('schema',table_schema,'table',table_name,'column',column_name,'type',data_type) ORDER BY table_schema,table_name,ordinal_position) FROM information_schema.columns WHERE (table_schema='storage' AND table_name='buckets') OR(table_schema='pgmq' AND table_name='meta') OR(table_schema='cron' AND table_name='job')),
 'data_api_role_settings',(SELECT jsonb_agg(jsonb_build_object('role',coalesce(r.rolname,'ALL'),'database',coalesce(d.datname,'ALL'),'setting',item)) FROM pg_db_role_setting s LEFT JOIN pg_roles r ON r.oid=s.setrole LEFT JOIN pg_database d ON d.oid=s.setdatabase CROSS JOIN LATERAL unnest(s.setconfig) item WHERE split_part(item,'=',1) IN ('pgrst.db_schemas','pgrst.db_extra_search_path','pgrst.db_pre_request')),
 'service_relations',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'kind',c.relkind) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p') AND ((n.nspname='public' AND c.relname IN ('profiles','push_tokens','notifications','push_throttle','premium_subscriptions','price_alert_rules')) OR (n.nspname='pgmq' AND (c.relname='meta' OR c.relname LIKE 'q_%' OR c.relname LIKE 'a_%'))))
) AS evidence;
ROLLBACK;

BEGIN TRANSACTION READ ONLY;
SET LOCAL statement_timeout='5s';
SET LOCAL lock_timeout='500ms';
SET LOCAL application_name='ce1_ce101_inventory';
SELECT jsonb_build_object(
 'captured_at',clock_timestamp(),
 'selected_test_account',jsonb_build_object('username','rruizosma','exact_case_insensitive_matches',(SELECT count(*) FROM (SELECT 1 FROM public.profiles WHERE lower(username)='rruizosma' LIMIT 2)s),'identity_session_verified',false),
 'storage_policy_expressions',(SELECT jsonb_agg(jsonb_build_object('name',policyname,'command',cmd,'using',qual,'check',with_check) ORDER BY policyname) FROM pg_policies WHERE schemaname='storage' AND tablename='objects'),
 'auth_lifecycle_triggers',(SELECT jsonb_agg(jsonb_build_object('trigger',t.tgname,'enabled',t.tgenabled,'function',fn.nspname||'.'||p.proname,'function_md5',md5(pg_get_functiondef(p.oid))) ORDER BY t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace fn ON fn.oid=p.pronamespace WHERE n.nspname='auth' AND c.relname='users' AND NOT t.tgisinternal),
 'realtime_publication_relations',(SELECT jsonb_agg(jsonb_build_object('publication',pubname,'schema',schemaname,'relation',tablename) ORDER BY schemaname,tablename) FROM pg_publication_tables WHERE pubname='supabase_realtime'),
 'queue_rpc_privileges',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE')) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='pgmq_public' AND p.prokind='f')
) AS evidence;
ROLLBACK;
